80	type volume struct {
81		id               string
82		poolID           string
83		sizeBytes        int64
84		createdSizeBytes int64
85		generation       int64
86		binding          string // "" when unbound
87		cloneSource      string // snapshot id when produced via a clone
88		tenant           string
89	}
