101		for i, d := range p.devices {
102			devices[i] = deviceView{ID: d.ID, CapacityBytes: d.CapacityBytes, FaultDomain: d.FaultDomain}
103		}
104		allocated := p.allocated()
105		return poolView{
106			ID:               p.id,
107			Devices:          devices,
108			RawCapacityBytes: p.rawCapacity,
109			AllocatedBytes:   allocated,
110			AvailableBytes:   p.rawCapacity - allocated,
111		}
112	}
