114	// store is the in-memory state of the service. It is wiped on restart.
115	type store struct {
116		mu          sync.RWMutex
117		pools       map[string]*pool
118		volumes     map[string]*volume
119		snapshots   map[string]*snapshot
120		buckets     map[string]*bucket
121		deviceOwner map[string]string
122		// auditEvents is the append-only audit log; auditSeq is the sequence of
123		// its last entry (0 while empty). Both are mutated under mu, together with
124		// the business state each event describes.
125		auditEvents []auditEvent
126		auditSeq    int64
127	}
128	
129	func newStore() *store {
130		return &store{
131			pools:       make(map[string]*pool),
132			volumes:     make(map[string]*volume),
133			snapshots:   make(map[string]*snapshot),
134			buckets:     make(map[string]*bucket),
135			deviceOwner: make(map[string]string),
136		}
137	}
138	
139	func validID(id string) bool {
140		return idPattern.MatchString(id)
141	}
142	
143	func (s *store) listPools(w http.ResponseWriter) {
144		s.mu.RLock()
145		ids := make([]string, 0, len(s.pools))
146		for id := range s.pools {
147			ids = append(ids, id)
148		}
149		sort.Strings(ids)
150		items := make([]poolView, 0, len(ids))
151		for _, id := range ids {
152			items = append(items, s.pools[id].view())
153		}
154		s.mu.RUnlock()
155		writeJSON(w, http.StatusOK, map[string]any{"items": items})
156	}
157	
158	func (s *store) getPool(w http.ResponseWriter, id string) {
159		if !validID(id) {
160			writeError(w, http.StatusBadRequest, "invalid_request")
161			return
162		}
163		s.mu.RLock()
164		p, ok := s.pools[id]
165		var v poolView
166		if ok {
167			v = p.view()
168		}
169		s.mu.RUnlock()
170		if !ok {
171			writeError(w, http.StatusNotFound, "pool_not_found")
172			return
173		}
174		writeJSON(w, http.StatusOK, v)
175	}
176	
177	func (s *store) createPool(w http.ResponseWriter, r *http.Request) {
178		var in createPoolInput
179		if !decodeRequest(r, &in) {
180			writeError(w, http.StatusBadRequest, "invalid_request")
181			return
182		}
183		// Validate the whole payload before touching any state so a failure
184		// never leaves a partial pool behind.
185		if !validID(in.ID) || len(in.Devices) == 0 {
186			writeError(w, http.StatusBadRequest, "invalid_request")
187			return
188		}
189		seen := make(map[string]bool, len(in.Devices))
190		var rawCapacity int64
191		for _, d := range in.Devices {
192			if !validID(d.ID) || d.CapacityBytes <= 0 || d.FaultDomain == "" || seen[d.ID] {
193				writeError(w, http.StatusBadRequest, "invalid_request")
194				return
195			}
196			if rawCapacity > math.MaxInt64-d.CapacityBytes {
197				writeError(w, http.StatusBadRequest, "invalid_request")
198				return
199			}
200			seen[d.ID] = true
201			rawCapacity += d.CapacityBytes
202		}
203	
204		s.mu.Lock()
205		defer s.mu.Unlock()
206		if _, ok := s.pools[in.ID]; ok {
207			writeError(w, http.StatusConflict, "pool_exists")
208			return
209		}
210		for _, d := range in.Devices {
211			if _, busy := s.deviceOwner[d.ID]; busy {
212				writeError(w, http.StatusConflict, "device_in_use")
213				return
214			}
215		}
216	
217		devices := append([]deviceInput(nil), in.Devices...)
218		p := &pool{
219			id:           in.ID,
220			devices:      devices,
221			rawCapacity:  rawCapacity,
222			reservations: make(map[string]reservation),
223			tenantUsed:   make(map[string]int64),
224			quotas:       make(map[string]int64),
225		}
226		s.pools[in.ID] = p
227		for _, d := range devices {
228			s.deviceOwner[d.ID] = in.ID
229		}
230		s.appendAudit(auditPoolCreated, storagePoolPath+"/"+in.ID, in.ID, 0)
231		writeJSON(w, http.StatusCreated, p.view())
232	}
233	
234	func (s *store) deletePool(w http.ResponseWriter, id string) {
235		if !validID(id) {
236			writeError(w, http.StatusBadRequest, "invalid_request")
237			return
238		}
239		s.mu.Lock()
240		defer s.mu.Unlock()
241		p, ok := s.pools[id]
242		if !ok {
243			writeError(w, http.StatusNotFound, "pool_not_found")
244			return
245		}
246		if len(p.reservations) > 0 || p.volumeBytes > 0 || p.snapshotBytes > 0 || p.objectBytes > 0 {
247			writeError(w, http.StatusConflict, "pool_not_empty")
248			return
249		}
250		// An empty bucket still blocks pool deletion even though it charges no
251		// bytes.
252		for _, b := range s.buckets {
253			if b.poolID == id {
254				writeError(w, http.StatusConflict, "pool_not_empty")
255				return
256			}
257		}
258		for _, d := range p.devices {
259			delete(s.deviceOwner, d.ID)
260		}
261		delete(s.pools, id)
262		s.appendAudit(auditPoolDeleted, storagePoolPath+"/"+id, id, 0)
263		w.WriteHeader(http.StatusNoContent)
264	}
265	
266	func (s *store) createReservation(w http.ResponseWriter, r *http.Request, poolID string) {
267		var in reservationInput
268		if !decodeRequest(r, &in) {
269			writeError(w, http.StatusBadRequest, "invalid_request")
270			return
271		}
272		tenant, tok := extractTenant(r.Header)
273		if !tok || !validID(poolID) || !validID(in.RequestID) || in.Bytes <= 0 {
274			writeError(w, http.StatusBadRequest, "invalid_request")
275			return
276		}
277	
278		s.mu.Lock()
279		defer s.mu.Unlock()
280		p, ok := s.pools[poolID]
281		if !ok {
282			writeError(w, http.StatusNotFound, "pool_not_found")
283			return
284		}
285		if existing, dup := p.reservations[in.RequestID]; dup {
286			if existing.bytes != in.Bytes || existing.tenant != tenant {
287				writeError(w, http.StatusConflict, "idempotency_conflict")
288				return
289			}
290			writeJSON(w, http.StatusOK, reservationView{PoolID: poolID, RequestID: existing.requestID, Bytes: existing.bytes})
291			return
292		}
293		// Holding the store lock makes the quota and capacity checks plus the
294		// charge atomic, so concurrent creates can never exceed either limit.
295		if p.tenantQuotaExceeded(tenant, in.Bytes) {
296			writeError(w, http.StatusConflict, "tenant_quota_exceeded")
297			return
298		}
299		allocated := p.allocated()
300		if allocated > p.rawCapacity-in.Bytes {
301			writeError(w, http.StatusConflict, "insufficient_capacity")
302			return
303		}
304		p.reservations[in.RequestID] = reservation{requestID: in.RequestID, bytes: in.Bytes, tenant: tenant}
305		p.tenantUsed[tenant] += in.Bytes
306		s.appendAudit(auditReservationCreated,
307			storagePoolPath+"/"+poolID+"/reservations/"+in.RequestID, poolID, in.Bytes)
308		writeJSON(w, http.StatusCreated, reservationView{PoolID: poolID, RequestID: in.RequestID, Bytes: in.Bytes})
309	}
310	
311	func (s *store) deleteReservation(w http.ResponseWriter, poolID, requestID string) {
312		if !validID(poolID) || !validID(requestID) {
313			writeError(w, http.StatusBadRequest, "invalid_request")
314			return
315		}
316		s.mu.Lock()
317		defer s.mu.Unlock()
318		p, ok := s.pools[poolID]
319		if !ok {
320			writeError(w, http.StatusNotFound, "pool_not_found")
321			return
322		}
323		// Deleting an unknown or already-deleted reservation is a success with
324		// no state change, so only a real deletion records an event.
325		if r, existed := p.reservations[requestID]; existed {
326			delete(p.reservations, requestID)
327			p.tenantUsed[r.tenant] -= r.bytes
328			s.appendAudit(auditReservationDeleted,
329				storagePoolPath+"/"+poolID+"/reservations/"+requestID, poolID, -r.bytes)
330		}
331		w.WriteHeader(http.StatusNoContent)
332	}
