33	// objectView is the public representation of an object after a write, and
34	// the summary shape used in object listings.
35	type objectView struct {
36		Key       string            `json:"key"`
37		SizeBytes int64             `json:"sizeBytes"`
38		Metadata  map[string]string `json:"metadata"`
39		ETag      string            `json:"etag"`
