42	// bucket is a namespace of objects bound to one pool. bytesUsed is kept in
43	// sync with the sum of its objects' sizes; the same total is charged to the
44	// pool as objectBytes. tenant owns the bucket; object bytes are charged to
45	// the tenant's usage in the pool.
46	type bucket struct {
47		id      string
48		poolID  string
49		tenant  string
50		objects map[string]*object
51	}
52	
53	func (b *bucket) bytesUsed() int64 {
54		var total int64
55		for _, o := range b.objects {
56			total += o.sizeBytes
57		}
58		return total
59	}
60	
61	func (b *bucket) view() bucketView {
62		return bucketView{ID: b.id, PoolID: b.poolID, ObjectCount: len(b.objects), BytesUsed: b.bytesUsed()}
63	}
64	
65	// object is a stored byte sequence with user metadata. etag is the quoted
66	// lowercase hex SHA-256 of content.
67	type object struct {
68		key       string
69		content   []byte
70		metadata  map[string]string
71		etag      string
72		sizeBytes int64
73	}
74	
75	func (o *object) view() objectView {
76		return objectView{Key: o.key, SizeBytes: o.sizeBytes, Metadata: o.metadata, ETag: o.etag}
77	}
