package server

import (
	"crypto/sha256"
	"encoding/hex"
	"io"
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// metaPrefix is the header prefix carrying user metadata on object writes.
// The constant is already in Go's canonical header form.
const metaPrefix = "X-Vaultgrid-Meta-"

type createBucketInput struct {
	ID     string `json:"id"`
	PoolID string `json:"poolId"`
}

// bucketView is the public representation of a bucket.
type bucketView struct {
	ID          string `json:"id"`
	PoolID      string `json:"poolId"`
	ObjectCount int    `json:"objectCount"`
	BytesUsed   int64  `json:"bytesUsed"`
}

// objectView is the public representation of an object after a write, and
// the summary shape used in object listings.
type objectView struct {
	Key       string            `json:"key"`
	SizeBytes int64             `json:"sizeBytes"`
	Metadata  map[string]string `json:"metadata"`
	ETag      string            `json:"etag"`
}

// bucket is a namespace of objects bound to one pool. bytesUsed is kept in
// sync with the sum of its objects' sizes; the same total is charged to the
// pool as objectBytes. tenant owns the bucket; object bytes are charged to
// the tenant's usage in the pool.
type bucket struct {
	id      string
	poolID  string
	tenant  string
	objects map[string]*object
}

func (b *bucket) bytesUsed() int64 {
	var total int64
	for _, o := range b.objects {
		total += o.sizeBytes
	}
	return total
}

func (b *bucket) view() bucketView {
	return bucketView{ID: b.id, PoolID: b.poolID, ObjectCount: len(b.objects), BytesUsed: b.bytesUsed()}
}

// object is a stored byte sequence with user metadata. etag is the quoted
// lowercase hex SHA-256 of content.
type object struct {
	key       string
	content   []byte
	metadata  map[string]string
	etag      string
	sizeBytes int64
}

func (o *object) view() objectView {
	return objectView{Key: o.key, SizeBytes: o.sizeBytes, Metadata: o.metadata, ETag: o.etag}
}

// routeBuckets dispatches /v1/buckets and its sub-paths. The object key is
// the remainder of the path after "objects/" (already URL-decoded once by
// the net/http layer) and may contain slashes, so it is not split here.
func (s *store) routeBuckets(w http.ResponseWriter, r *http.Request) {
	rest := strings.TrimPrefix(r.URL.Path, bucketPath)
	if rest == "" {
		switch r.Method {
		case http.MethodGet:
			s.listBuckets(w)
		case http.MethodPost:
			s.createBucket(w, r)
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodPost)
		}
		return
	}
	// rest begins with "/"; the bucket id is the single next segment.
	bucketID, tail, found := strings.Cut(rest[1:], "/")
	if bucketID == "" {
		writeError(w, http.StatusNotFound, "not_found")
		return
	}
	if !found {
		switch r.Method {
		case http.MethodGet:
			s.getBucket(w, bucketID)
		case http.MethodDelete:
			s.deleteBucket(w, bucketID)
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodDelete)
		}
		return
	}
	if tail == "objects" {
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		s.listObjects(w, r, bucketID)
		return
	}
	if key, ok := strings.CutPrefix(tail, "objects/"); ok {
		switch r.Method {
		case http.MethodPut:
			s.putObject(w, r, bucketID, key)
		case http.MethodGet:
			s.getObject(w, r, bucketID, key, false)
		case http.MethodHead:
			s.getObject(w, r, bucketID, key, true)
		case http.MethodDelete:
			s.deleteObject(w, r, bucketID, key)
		default:
			methodNotAllowed(w, http.MethodPut, http.MethodGet, http.MethodHead, http.MethodDelete)
		}
		return
	}
	writeError(w, http.StatusNotFound, "not_found")
}

func (s *store) listBuckets(w http.ResponseWriter) {
	s.mu.RLock()
	ids := make([]string, 0, len(s.buckets))
	for id := range s.buckets {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	items := make([]bucketView, 0, len(ids))
	for _, id := range ids {
		items = append(items, s.buckets[id].view())
	}
	s.mu.RUnlock()
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

func (s *store) getBucket(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.RLock()
	b, ok := s.buckets[id]
	var v bucketView
	if ok {
		v = b.view()
	}
	s.mu.RUnlock()
	if !ok {
		writeError(w, http.StatusNotFound, "bucket_not_found")
		return
	}
	writeJSON(w, http.StatusOK, v)
}

func (s *store) createBucket(w http.ResponseWriter, r *http.Request) {
	var in createBucketInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	tenant, tok := extractTenant(r.Header)
	if !tok || !validID(in.ID) || !validID(in.PoolID) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	if existing, dup := s.buckets[in.ID]; dup {
		if existing.poolID == in.PoolID && existing.tenant == tenant {
			writeJSON(w, http.StatusOK, existing.view())
			return
		}
		writeError(w, http.StatusConflict, "bucket_exists")
		return
	}
	if _, ok := s.pools[in.PoolID]; !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	s.buckets[in.ID] = &bucket{id: in.ID, poolID: in.PoolID, tenant: tenant, objects: make(map[string]*object)}
	s.appendAudit(auditBucketCreated, bucketPath+"/"+in.ID, in.PoolID, 0)
	writeJSON(w, http.StatusCreated, s.buckets[in.ID].view())
}

func (s *store) deleteBucket(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	b, ok := s.buckets[id]
	if !ok {
		writeError(w, http.StatusNotFound, "bucket_not_found")
		return
	}
	if len(b.objects) > 0 {
		writeError(w, http.StatusConflict, "bucket_not_empty")
		return
	}
	delete(s.buckets, id)
	s.appendAudit(auditBucketDeleted, bucketPath+"/"+id, b.poolID, 0)
	w.WriteHeader(http.StatusNoContent)
}

// validObjectKey reports whether key is 1..1024 bytes of valid UTF-8 with no
// control characters.
func validObjectKey(key string) bool {
	if len(key) == 0 || len(key) > 1024 || !utf8.ValidString(key) {
		return false
	}
	for _, r := range key {
		if unicode.IsControl(r) {
			return false
		}
	}
	return true
}

// extractMetadata collects the X-Vaultgrid-Meta-* request headers into a
// metadata map keyed by the suffix after the prefix. A header with an empty
// suffix or a value that is not valid UTF-8 or carries control characters
// makes the whole request invalid.
func extractMetadata(h http.Header) (map[string]string, bool) {
	meta := make(map[string]string)
	for name, values := range h {
		suffix, ok := strings.CutPrefix(name, metaPrefix)
		if !ok {
			continue
		}
		if suffix == "" {
			return nil, false
		}
		for _, v := range values {
			if !utf8.ValidString(v) {
				return nil, false
			}
			for _, r := range v {
				if unicode.IsControl(r) {
					return nil, false
				}
			}
		}
		meta[suffix] = strings.Join(values, ", ")
	}
	return meta, true
}

// parsePrecondition validates the conditional-write headers. It returns the
// If-Match etag ("" when absent) and whether If-None-Match: * was given. ok
// is false when both headers are present or either has an unsupported form.
func parsePrecondition(h http.Header) (ifMatch string, ifNoneMatchStar, ok bool) {
	matches, hasMatch := h["If-Match"]
	noneMatches, hasNoneMatch := h["If-None-Match"]
	if hasMatch && hasNoneMatch {
		return "", false, false
	}
	if hasMatch {
		if len(matches) != 1 || !isQuotedETag(matches[0]) {
			return "", false, false
		}
		return matches[0], false, true
	}
	if hasNoneMatch {
		if len(noneMatches) != 1 || noneMatches[0] != "*" {
			return "", false, false
		}
		return "", true, true
	}
	return "", false, true
}

// isQuotedETag reports whether v looks like a quoted hex etag, e.g.
// "9f86d081...". The content is not checked against any object here.
func isQuotedETag(v string) bool {
	if len(v) < 2 || v[0] != '"' || v[len(v)-1] != '"' {
		return false
	}
	inner := v[1 : len(v)-1]
	if inner == "" {
		return false
	}
	for _, c := range inner {
		if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
			return false
		}
	}
	return true
}

func etagOf(content []byte) string {
	sum := sha256.Sum256(content)
	return `"` + hex.EncodeToString(sum[:]) + `"`
}

func (s *store) putObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
	if !validID(bucketID) || !validObjectKey(key) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if r.URL.RawQuery != "" {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	metadata, ok := extractMetadata(r.Header)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	ifMatch, ifNoneMatchStar, ok := parsePrecondition(r.Header)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	content, err := io.ReadAll(r.Body)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	etag := etagOf(content)
	size := int64(len(content))

	s.mu.Lock()
	defer s.mu.Unlock()
	b, ok := s.buckets[bucketID]
	if !ok {
		writeError(w, http.StatusNotFound, "bucket_not_found")
		return
	}
	existing := b.objects[key]
	if ifMatch != "" && (existing == nil || existing.etag != ifMatch) {
		writeError(w, http.StatusPreconditionFailed, "precondition_failed")
		return
	}
	if ifNoneMatchStar && existing != nil {
		writeError(w, http.StatusPreconditionFailed, "precondition_failed")
		return
	}
	var oldSize int64
	if existing != nil {
		oldSize = existing.sizeBytes
	}
	p := s.pools[b.poolID]
	// The store lock makes the quota and capacity checks plus the charge
	// atomic, so concurrent writes can never exceed either limit, and a failed
	// write leaves the old object and its metadata untouched. Objects inherit
	// the bucket's tenant; only a growing write can breach the quota.
	if delta := size - oldSize; delta > 0 && p.tenantQuotaExceeded(b.tenant, delta) {
		writeError(w, http.StatusConflict, "tenant_quota_exceeded")
		return
	}
	if p.allocated() > p.rawCapacity-(size-oldSize) {
		writeError(w, http.StatusConflict, "insufficient_capacity")
		return
	}
	b.objects[key] = &object{key: key, content: content, metadata: metadata, etag: etag, sizeBytes: size}
	p.objectBytes += size - oldSize
	p.tenantUsed[b.tenant] += size - oldSize
	// An overwrite is recorded even when the size delta is zero.
	resource := bucketPath + "/" + bucketID + "/objects/" + key
	if existing != nil {
		s.appendAudit(auditObjectOverwritten, resource, b.poolID, size-oldSize)
	} else {
		s.appendAudit(auditObjectCreated, resource, b.poolID, size)
	}
	status := http.StatusCreated
	if existing != nil {
		status = http.StatusOK
	}
	w.Header().Set("ETag", etag)
	writeJSON(w, status, b.objects[key].view())
}

// getObject serves both GET and HEAD; headOnly suppresses the body.
func (s *store) getObject(w http.ResponseWriter, r *http.Request, bucketID, key string, headOnly bool) {
	if !validID(bucketID) || !validObjectKey(key) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if r.URL.RawQuery != "" {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.RLock()
	b, ok := s.buckets[bucketID]
	var o *object
	if ok {
		o = b.objects[key]
	}
	s.mu.RUnlock()
	if !ok {
		writeError(w, http.StatusNotFound, "bucket_not_found")
		return
	}
	if o == nil {
		writeError(w, http.StatusNotFound, "object_not_found")
		return
	}
	for name, value := range o.metadata {
		w.Header().Set(metaPrefix+name, value)
	}
	w.Header().Set("ETag", o.etag)
	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Length", strconv.FormatInt(o.sizeBytes, 10))
	w.WriteHeader(http.StatusOK)
	if !headOnly {
		_, _ = w.Write(o.content)
	}
}

func (s *store) deleteObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
	if !validID(bucketID) || !validObjectKey(key) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if r.URL.RawQuery != "" {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	b, ok := s.buckets[bucketID]
	if !ok {
		writeError(w, http.StatusNotFound, "bucket_not_found")
		return
	}
	// Deleting an unknown or already-deleted object is a success with no
	// state change, so only a real deletion records an event.
	if o, exists := b.objects[key]; exists {
		s.pools[b.poolID].objectBytes -= o.sizeBytes
		s.pools[b.poolID].tenantUsed[b.tenant] -= o.sizeBytes
		delete(b.objects, key)
		s.appendAudit(auditObjectDeleted, bucketPath+"/"+bucketID+"/objects/"+key, b.poolID, -o.sizeBytes)
	}
	w.WriteHeader(http.StatusNoContent)
}

// parsePrefixQuery accepts an empty query or exactly one "prefix=<value>"
// pair. Duplicated or unknown parameters yield ok=false.
func parsePrefixQuery(raw string) (string, bool) {
	if raw == "" {
		return "", true
	}
	var prefix string
	found := false
	for _, pair := range strings.Split(raw, "&") {
		k, value, ok := strings.Cut(pair, "=")
		if !ok {
			return "", false
		}
		decodedKey, err := url.QueryUnescape(k)
		if err != nil || decodedKey != "prefix" || found {
			return "", false
		}
		decodedValue, err := url.QueryUnescape(value)
		if err != nil {
			return "", false
		}
		prefix, found = decodedValue, true
	}
	return prefix, found
}

func (s *store) listObjects(w http.ResponseWriter, r *http.Request, bucketID string) {
	prefix, ok := parsePrefixQuery(r.URL.RawQuery)
	if !ok || !validID(bucketID) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.RLock()
	b, ok := s.buckets[bucketID]
	var items []objectView
	if ok {
		keys := make([]string, 0, len(b.objects))
		for k := range b.objects {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		items = make([]objectView, 0, len(keys))
		for _, k := range keys {
			if strings.HasPrefix(k, prefix) {
				items = append(items, b.objects[k].view())
			}
		}
	}
	s.mu.RUnlock()
	if !ok {
		writeError(w, http.StatusNotFound, "bucket_not_found")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

package server

import (
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"
)

// auditAction enumerates the recorded state-changing operations. Failures,
// read-only requests and successful requests that change no state are never
// recorded.
type auditAction string

const (
	auditPoolCreated        auditAction = "pool.created"
	auditPoolDeleted        auditAction = "pool.deleted"
	auditReservationCreated auditAction = "reservation.created"
	auditReservationDeleted auditAction = "reservation.deleted"
	auditVolumeCreated      auditAction = "volume.created"
	auditVolumeDeleted      auditAction = "volume.deleted"
	auditVolumeBound        auditAction = "volume.bound"
	auditVolumeUnbound      auditAction = "volume.unbound"
	auditVolumeResized      auditAction = "volume.resized"
	auditSnapshotCreated    auditAction = "snapshot.created"
	auditSnapshotDeleted    auditAction = "snapshot.deleted"
	auditCloneCreated       auditAction = "clone.created"
	auditBucketCreated      auditAction = "bucket.created"
	auditBucketDeleted      auditAction = "bucket.deleted"
	auditObjectCreated      auditAction = "object.created"
	auditObjectOverwritten  auditAction = "object.overwritten"
	auditObjectDeleted      auditAction = "object.deleted"
	auditTenantQuotaCreated auditAction = "tenant-quota.created"
	auditTenantQuotaUpdated auditAction = "tenant-quota.updated"
	auditTenantQuotaDeleted auditAction = "tenant-quota.deleted"
)

// auditEventView is the public representation of an audit event.
type auditEventView struct {
	Sequence   int64  `json:"sequence"`
	Action     string `json:"action"`
	Resource   string `json:"resource"`
	PoolID     string `json:"poolId"`
	BytesDelta int64  `json:"bytesDelta"`
}

// auditEvent is one entry of the in-memory audit log. Events are appended
// while holding the store write lock in the same critical section as the
// business state and capacity counters, so an event and the change it
// describes commit atomically: a committed response is always followed by a
// visible event, and a failure leaves no event. The log lives in memory and
// is wiped on restart.
type auditEvent struct {
	sequence   int64
	action     auditAction
	resource   string
	poolID     string
	bytesDelta int64
}

func (e *auditEvent) view() auditEventView {
	return auditEventView{
		Sequence:   e.sequence,
		Action:     string(e.action),
		Resource:   e.resource,
		PoolID:     e.poolID,
		BytesDelta: e.bytesDelta,
	}
}

// appendAudit assigns the next sequence and appends an event. The caller must
// hold s.mu for writing; numbering inside the commit critical section orders
// concurrent commits by the order in which they actually committed.
func (s *store) appendAudit(action auditAction, resource, poolID string, bytesDelta int64) {
	s.auditSeq++
	s.auditEvents = append(s.auditEvents, auditEvent{
		sequence:   s.auditSeq,
		action:     action,
		resource:   resource,
		poolID:     poolID,
		bytesDelta: bytesDelta,
	})
}

// auditEventsPath is the route constant for the audit events endpoint.
const auditEventsPath = "/v1/audit-events"

// auditEventsQuery is the parsed GET /v1/audit-events query.
type auditEventsQuery struct {
	after   int64
	limit   int
	poolID  string
	hasPool bool
}

// parseAuditEventsQuery accepts an empty query or any combination of the
// "after", "limit" and "poolId" parameters, each given at most once and always
// with a value. Defaults are after=0, limit=100, no pool filter. Duplicated,
// unknown, value-less or malformed parameters yield ok=false.
func parseAuditEventsQuery(raw string) (auditEventsQuery, bool) {
	q := auditEventsQuery{limit: 100}
	if raw == "" {
		return q, true
	}
	seenAfter, seenLimit, seenPool := false, false, false
	for _, pair := range strings.Split(raw, "&") {
		k, value, found := strings.Cut(pair, "=")
		if !found {
			return q, false
		}
		key, err := url.QueryUnescape(k)
		if err != nil {
			return q, false
		}
		decoded, err := url.QueryUnescape(value)
		if err != nil {
			return q, false
		}
		switch key {
		case "after":
			if seenAfter || !isNonNegativeDecimal(decoded) {
				return q, false
			}
			seenAfter = true
			n, err := strconv.ParseInt(decoded, 10, 64)
			if err != nil {
				return q, false
			}
			q.after = n
		case "limit":
			if seenLimit || !isNonNegativeDecimal(decoded) {
				return q, false
			}
			seenLimit = true
			n, err := strconv.ParseInt(decoded, 10, 64)
			if err != nil || n < 1 || n > 1000 {
				return q, false
			}
			q.limit = int(n)
		case "poolId":
			if seenPool || decoded == "" || !validID(decoded) {
				return q, false
			}
			seenPool = true
			q.poolID = decoded
			q.hasPool = true
		default:
			return q, false
		}
	}
	return q, true
}

// isNonNegativeDecimal reports whether s is one or more ASCII decimal digits,
// rejecting signs, spaces and exponent notation.
func isNonNegativeDecimal(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// auditEventsList is the response envelope.
type auditEventsList struct {
	Items     []auditEventView `json:"items"`
	NextAfter int64            `json:"nextAfter"`
	HasMore   bool             `json:"hasMore"`
}

// listAuditEvents handles GET /v1/audit-events. The whole page is selected
// under a single read lock, so items and hasMore describe one consistent read
// state even while other requests commit new events.
func (s *store) listAuditEvents(w http.ResponseWriter, r *http.Request) {
	q, ok := parseAuditEventsQuery(r.URL.RawQuery)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.RLock()
	defer s.mu.RUnlock()
	if q.hasPool {
		if _, exists := s.pools[q.poolID]; !exists {
			writeError(w, http.StatusNotFound, "pool_not_found")
			return
		}
	}

	// Sequences are dense and the slice is append-only, so index order is
	// sequence order. Jump to the first event with sequence > after.
	first := sort.Search(len(s.auditEvents), func(i int) bool {
		return s.auditEvents[i].sequence > q.after
	})
	items := make([]auditEventView, 0, q.limit)
	hasMore := false
	for i := first; i < len(s.auditEvents); i++ {
		e := s.auditEvents[i]
		if q.hasPool && e.poolID != q.poolID {
			continue
		}
		if len(items) >= q.limit {
			// A matching event beyond the page (in this same read state)
			// remains.
			hasMore = true
			break
		}
		items = append(items, e.view())
	}
	nextAfter := q.after
	if len(items) > 0 {
		nextAfter = items[len(items)-1].Sequence
	}
	writeJSON(w, http.StatusOK, auditEventsList{Items: items, NextAfter: nextAfter, HasMore: hasMore})
}

